import{_ as n,o as s,c as e,a2 as t}from"./chunks/framework.D3fmyz3M.js";const h=JSON.parse('{"title":"工程化总览","description":"从能跑到能上线，需要补齐的五件事。","frontmatter":{"title":"工程化总览","description":"从能跑到能上线，需要补齐的五件事。"},"headers":[],"relativePath":"advanced/index.md","filePath":"advanced/index.md","lastUpdated":1792674288000}'),l={name:"advanced/index.md"};function i(p,a,r,d,c,o){return s(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="工程化总览" tabindex="-1">工程化总览 <a class="header-anchor" href="#工程化总览" aria-label="Permalink to &quot;工程化总览&quot;">​</a></h1><p>示例能跑，只证明“技术可行”。要上线，还要补齐：</p><table tabindex="0"><thead><tr><th>主题</th><th>解决的问题</th><th>章节</th></tr></thead><tbody><tr><td>部署</td><td>独立发布、灰度、回滚</td><td><a href="/micro-frontend-docs/advanced/deployment">独立部署与灰度</a></td></tr><tr><td>监控</td><td>错误定位、告警、链路</td><td><a href="/micro-frontend-docs/advanced/error-monitoring">错误边界与监控</a></td></tr><tr><td>性能</td><td>首屏、缓存、预加载</td><td><a href="/micro-frontend-docs/advanced/performance">性能优化</a></td></tr><tr><td>治理</td><td>版本、契约、规范</td><td><a href="/micro-frontend-docs/advanced/governance-security">治理与安全</a></td></tr><tr><td>安全</td><td>沙箱边界、CSP、供应链</td><td><a href="/micro-frontend-docs/advanced/governance-security">治理与安全</a></td></tr></tbody></table><h2 id="上线前的最低要求" tabindex="-1">上线前的最低要求 <a class="header-anchor" href="#上线前的最低要求" aria-label="Permalink to &quot;上线前的最低要求&quot;">​</a></h2><ul><li>[ ] 每个子应用有独立仓库与独立流水线。</li><li>[ ] 子应用产物有版本号，可回滚。</li><li>[ ] 主应用能识别子应用版本并做兼容处理。</li><li>[ ] 关键错误能上报到统一平台。</li><li>[ ] 有 Source Map，能还原压缩代码。</li><li>[ ] 有一个可灰度、可开关的降级方案。</li><li>[ ] 有跨应用日志追踪 ID。</li></ul><h2 id="一张部署拓扑" tabindex="-1">一张部署拓扑 <a class="header-anchor" href="#一张部署拓扑" aria-label="Permalink to &quot;一张部署拓扑&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户</span></span>
<span class="line"><span> │</span></span>
<span class="line"><span> ├─ CDN / 网关</span></span>
<span class="line"><span> │    ├─ /            → 主应用（index.html）</span></span>
<span class="line"><span> │    ├─ /order/*     → 订单子应用（可选）</span></span>
<span class="line"><span> │    └─ /product/*   → 商品子应用（可选）</span></span>
<span class="line"><span> │</span></span>
<span class="line"><span> └─ 运行时</span></span>
<span class="line"><span>      ├─ 主应用加载子应用清单（版本 + URL）</span></span>
<span class="line"><span>      ├─ 按路由 / 灰度规则选择版本</span></span>
<span class="line"><span>      └─ 失败时降级到稳定版本</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>运行时加载型方案（qiankun、micro-app、wujie）通常只需要：</p><ul><li>主应用部署一次。</li><li>子应用各自部署，主应用通过配置或接口拿到子应用 URL。</li></ul><p>构建时共享型（Module Federation）需要额外保证：</p><ul><li>remote 先部署可用。</li><li><code>remoteEntry</code> 地址稳定。</li><li>共享依赖版本兼容。</li></ul><h2 id="建议的目录与职责" tabindex="-1">建议的目录与职责 <a class="header-anchor" href="#建议的目录与职责" aria-label="Permalink to &quot;建议的目录与职责&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>apps/</span></span>
<span class="line"><span>├── shell/            # 主应用：路由、布局、鉴权、监控</span></span>
<span class="line"><span>├── order/            # 订单子应用</span></span>
<span class="line"><span>├── product/          # 商品子应用</span></span>
<span class="line"><span>└── shared/           # 共享类型、工具、设计 token</span></span>
<span class="line"><span>infra/</span></span>
<span class="line"><span>├── deploy/           # 部署脚本与配置</span></span>
<span class="line"><span>└── monitor/          # 监控与告警配置</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>主应用不要承载业务逻辑，只保留：</p><ul><li>布局与导航。</li><li>路由调度。</li><li>登录与权限。</li><li>全局错误处理。</li><li>子应用注册表。</li></ul><h2 id="团队协作约定" tabindex="-1">团队协作约定 <a class="header-anchor" href="#团队协作约定" aria-label="Permalink to &quot;团队协作约定&quot;">​</a></h2><table tabindex="0"><thead><tr><th>事项</th><th>约定</th></tr></thead><tbody><tr><td>路由前缀</td><td>每个子应用固定前缀，禁止跨域占用</td></tr><tr><td>通信</td><td>只通过约定的 props / 事件 / 全局状态</td></tr><tr><td>样式</td><td>禁止全局选择器，必须加命名空间</td></tr><tr><td>构建</td><td>统一 Node / 包管理器版本</td></tr><tr><td>发布</td><td>子应用独立发版，主应用维护兼容矩阵</td></tr><tr><td>回滚</td><td>每个子应用保留最近 N 个版本</td></tr></tbody></table><h2 id="先做减法" tabindex="-1">先做减法 <a class="header-anchor" href="#先做减法" aria-label="Permalink to &quot;先做减法&quot;">​</a></h2><p>工程化最容易过度设计。建议按顺序补：</p><ol><li>能回滚。</li><li>能定位错误。</li><li>能灰度。</li><li>再谈性能优化与自动化治理。</li></ol><p>没有回滚与监控的微前端，不建议上核心业务。</p><p>继续阅读：<a href="/micro-frontend-docs/advanced/deployment">独立部署与灰度</a>。</p>`,22)])])}const u=n(l,[["render",i]]);export{h as __pageData,u as default};
